class Solution {
public:
    int numberOfArithmeticSlices(vector<int>& nums) {
        int n = (int)nums.size();
        if (n < 3) return 0;
        vector<unordered_map<long long, long long>> dp(n);
        long long ans = 0;
        for (int j = 1; j < n; j++) {
            for (int i = 0; i < j; i++) {
                long long d = (long long)nums[j] - (long long)nums[i];
                long long cnt = 0;
                auto it = dp[i].find(d);
                if (it != dp[i].end()) cnt = it->second;
                ans += cnt;
                dp[j][d] += cnt + 1;
            }
        }
        return (int)ans;
    }
};
